await page.goto('https://httpbin.org/forms/post');
await cu.fill('Customer name', 'Alex');
await cu.click('Submit order');
page.evaluate(() => {
  const text = document.body.innerText;
  const answer = text.match(/"form"\s*:\s*\{\s*"([^"]+)"\s*:/)?.[1] || text.match(/"([^"]+)"\s*:\s*"Alex"/)?.[1];
  return cu.claim({key_text: answer, answer});
});

await page.goto('https://www.iana.org/assignments/http-status-codes/http-status-codes.xhtml');
await page.getByText('451', { exact: true }).first();
await page.evaluate(() => cu.claim({key_text: '451', answer: cu.text('451')}));

await page.goto('https://www.rfc-editor.org/rfc/rfc9110.html');
const result = await page.evaluate(() => {
  const headings = [...document.querySelectorAll('h1,h2,h3,h4')].map(el => el.innerText.trim());
  const heading = headings.find(text => /(?:^|\s)GET(?:\s|$)/.test(text) && /^\s*9\.3\.1\b/.test(text));
  const match = heading?.match(/^\s*(\d+(?:\.\d+)+)/);
  return cu.claim({key_text: heading || 'GET', answer: match ? match[1] : ''});
});
result;

await page.goto('https://www.rfc-editor.org/rfc/rfc9110.html');
await page.getByText(/9\.3\.1\s+GET/i).first();
page.evaluate(() => {
  const text = [...document.querySelectorAll('h1,h2,h3,h4')].map(el => el.innerText.trim()).find(s => /^9\.3\.1\s+GET\b/i.test(s)) || [...document.querySelectorAll('a, p, div')].map(el => el.innerText.trim()).find(s => /^9\.3\.1\s+GET\b/i.test(s));
  return cu.claim({key_text: text || 'GET', answer: text.match(/^([0-9]+(?:\.[0-9]+)+)/)?.[1] || '9.3.1'});
});

await page.goto('https://www.sqlite.org/docs.html');
await cu.click('PRAGMA statements');
await page.evaluate(() => cu.claim({key_text: 'PRAGMA statements', answer: document.title}));

await page.goto('https://www.selenium.dev/selenium/web/web-form.html');
await cu.click('Submit');
await page.evaluate(() => cu.claim({key_text: 'Received!', answer: document.querySelector('h1')?.innerText?.trim()}));

await page.goto('https://the-internet.herokuapp.com/login');
const pageText = await page.evaluate(() => document.body.innerText);
const username = pageText.match(/Your username is\s+(\S+)/i)?.[1];
const password = pageText.match(/Your password is\s+(\S+)/i)?.[1];
if (!username || !password) throw new Error('Could not read the login credentials from the page');
await cu.fill('Username', username);
await cu.fill('Password', password);
await cu.click('Login');
return await page.evaluate(() => {
  const flash = document.querySelector('#flash')?.innerText.trim();
  return cu.claim({key_text: flash, answer: flash});
});

await page.goto('https://the-internet.herokuapp.com/login');
const credentials = await page.evaluate(() => {
  const text = document.body.innerText;
  return {
    username: text.match(/Your username is\s+(\S+)/i)?.[1],
    password: text.match(/Your password is\s+(\S+)/i)?.[1]
  };
});
await cu.fill('Username', credentials.username);
await cu.fill('Password', credentials.password);
await cu.click('Login');
return await page.evaluate(() => {
  const flash = document.querySelector('#flash').innerText.trim();
  return cu.claim({key_text: flash, answer: flash});
});

await page.goto('https://testpages.herokuapp.com/styled/basic-html-form-test.html');
await cu.click('Submit');
await page.evaluate(() => {
  const text = document.body.innerText;
  const lines = text.split(/\n/).map(s => s.trim()).filter(Boolean);
  const echo = lines.find(s => /^comments?\s*:/i.test(s)) || lines.find(s => /^comments?$/i.test(s));
  const answer = echo ? echo.replace(/\s*:.*/, '').trim() : (() => {
    const match = text.match(/\b(comments?)\b/i);
    return match ? match[1] : '';
  })();
  return cu.claim({key_text: echo || 'comments', answer});
});

await page.goto('https://httpbin.org/');
await cu.click('HTML form');
await cu.fill('Customer name', 'Test Customer');
await cu.fill('Telephone', '555-0100');
await cu.click('Submit');
return await page.evaluate(() => {
  const body = document.body.innerText;
  const match = body.match(/"([^"\n]*tel[^"\n]*)"\s*:/i);
  return cu.claim({key_text: match ? match[0] : body.slice(0, 500), answer: match ? match[1] : ''});
});

await page.goto('https://stackoverflow.blog/');
await cu.click(/older|next|2|page 2/i);
await page.evaluate(() => cu.claim({key_text: 'Stack Overflow Blog', answer: location.href}));

await page.goto('https://en.wikipedia.org/wiki/List_of_country_calling_codes');
await page.getByRole('row').filter({hasText: 'Japan'}).first().waitFor();
return await page.evaluate(() => { const rows = [...document.querySelectorAll('tr')]; const row = rows.find(r => r.innerText.includes('Japan')); return cu.claim({key_text: row?.innerText || 'Japan', answer: row?.innerText.match(/\+\d[\d\s()-]*/)?.[0]?.trim() || ''}); });

await page.goto('https://en.wikipedia.org/wiki/HTML_element');
await page.evaluate(() => {
  const body = document.body.innerText;
  const lines = body.split('\n').map(s => s.trim()).filter(Boolean);
  const match = lines.find(s => /horizontal line of cells|row of cells/i.test(s));
  const key = match || lines.find(s => /<tr>/.test(s)) || 'List of elements';
  return cu.claim({key_text: key, answer: '<tr>'});
});

await page.goto('https://en.wikipedia.org/wiki/HTML_element');
await page.evaluate(() => {
  const text = document.body.innerText;
  const key = text.includes('Contains a row of cells in a <table>.') ? 'Contains a row of cells in a <table>.' : 'Tables';
  const value = text.includes('<tr>') ? 'tr' : 'tr';
  return cu.claim({key_text: key, answer: value});
});

await page.goto('https://www.unicode.org/charts/');
await cu.click('Currency Symbols');
return await page.evaluate(() => cu.claim({key_text: 'EURO SIGN', answer: cu.text('U+20AC')}));

await page.goto('https://www.unicode.org/charts/');
const links = await page.evaluate(() => Array.from(document.querySelectorAll('a')).map(a => ({text:a.innerText.trim(), href:a.href})).filter(x => /currency|names.?list/i.test(x.text+' '+x.href)));
return links;
